import{_ as i}from"./chunks/cover_image.CgCjIhXF.js";import{_ as l,c as a,ag as r,o}from"./chunks/framework.kMCHP7uL.js";const _=JSON.parse('{"title":"什麼是 Zig","description":"","frontmatter":{"outline":"deep","showVersion":false},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),t={name:"index.md"};function n(p,e,c,d,s,g){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="什麼是-zig" tabindex="-1">什麼是 Zig <a class="header-anchor" href="#什麼是-zig" aria-label="Permalink to &quot;什麼是 Zig&quot;">​</a></h1><p>根據其官網所述：</p><blockquote><p>Zig 是一種通用的編程語言和工具鏈，用於維護健壯、最優和可重用的軟件</p></blockquote><p>這樣的概念解釋可能比較模糊，我們來看看維基百科怎麼說的：</p><blockquote><p>Zig 是一種命令式、通用、靜態類型、編譯的系統編程語言，由 Andrew Kelley 設計。 它旨在替代 C 編程語言，其目標是更小，編程更簡單，同時還提供現代功能，新的優化和各種安全機制， 同時不像其他語言那樣對運行時安全性的要求。</p></blockquote><blockquote><p>語言簡單性的改進與流控制、函數調用、庫導入、變量聲明和 Unicode 支持有關。 此外，該語言不使用宏或預處理器指令。從現代語言中採用的功能包括添加編譯時泛型類型， 允許函數處理各種數據，以及一小組新的編譯器指令，以允許使用反射訪問有關這些類型的信息。 Zig 還旨在提高代碼的安全性，它不提供垃圾回收（GC），但是使用可選類型代替 <code>null</code> ，這避免了空指針的出現。</p></blockquote><p><img src="'+i+'" alt="Cover Image" title="Cover Image" loading="lazy"></p><h2 id="為何使用-zig" tabindex="-1">為何使用 Zig <a class="header-anchor" href="#為何使用-zig" aria-label="Permalink to &quot;為何使用 Zig&quot;">​</a></h2><p>從本質上看，Zig 是一門 <code>low level</code> 的高級語言，它和 C 很像，但解決了 C 的一些歷史遺留問題，並提供了完善的工具鏈，而且它可選支持 <code>libc</code>。</p><p>一切都是強制顯式聲明式，這使得代碼閱讀很輕鬆！</p><p>如果你是嵌入式開發，亦或者對速度有很高的要求，還不想使用心智負擔太高的其他高級語言，或許 Zig 很適合你。</p><h2 id="特點" tabindex="-1">特點 <a class="header-anchor" href="#特點" aria-label="Permalink to &quot;特點&quot;">​</a></h2><ul><li>類型是一等公民</li><li>無隱式執行</li><li>手動內存控制，精確的內存洩漏跟蹤</li><li>完善的堆棧跟蹤（在裸機器上也可以）</li><li>對交叉編譯的一流支持</li><li>標準庫集成 libc，但不依賴它</li><li>可選類型代替 <code>null</code>，詳見 <a href="https://www.lucidchart.com/techblog/2015/08/31/the-worst-mistake-of-computer-science/" target="_blank" rel="noreferrer">計算機科學中最嚴重的錯誤</a></li><li>編譯期（可以簡單看作在編譯時執行的函數）執行實現泛型和反射</li><li>無需 FFI/bindings 的 C 庫集成</li><li>非常強大的構建系統</li></ul><p>有幾點是非常值得單獨拿出來說明一下的：</p><p><em>Zig 會要求你顯式傳遞和管理你的內存，並且編譯時就會跟蹤你的內存是否發生洩漏， 高明的可選類型（這和 rust 的 option 有異曲同工之妙），強大的編譯期運行，你可實現很多花哨的操作，而構建系統則被很多 C 項目拿去作為工具鏈使用</em></p><h2 id="瞭解更多" tabindex="-1">瞭解更多？ <a class="header-anchor" href="#瞭解更多" aria-label="Permalink to &quot;瞭解更多？&quot;">​</a></h2><p>查看<a href="./appendix/well-known-lib.html">這裡</a>，列出了一些積極維護的 zig 庫或者實現</p><p>以下列出了，可以在線執行 zig 的平臺：</p><ul><li><a href="https://playground.zigtools.org/" target="_blank" rel="noreferrer">zig-playground</a></li><li><a href="https://zig-play.dev/" target="_blank" rel="noreferrer">zig-play</a></li><li><a href="https://riju.codes/zig" target="_blank" rel="noreferrer">Riju</a></li></ul>',19)]))}const m=l(t,[["render",n]]);export{_ as __pageData,m as default};
